// One scan run. The daily schedule runs in "live" scope; the test workflow passes scope "eval", a day and a run id.
// The fictional sites have 5 versions (days 1-5). Outside tests the simulated day follows the calendar.
const input = $input.first().json || {};
const scope = input.scope === 'eval' ? 'eval' : 'live';
const day = Number(input.day) >= 1 && Number(input.day) <= 5 ? Number(input.day) : ($now.ordinal % 5) + 1;
const runId = input.run_id || ('LIVE-' + $now.setZone('Europe/Warsaw').toFormat('yyyyMMdd-HHmm'));
return [{ json: { scope, day, run_id: runId, started_at: $now.toISO() } }];

// One request per client homepage. Only public pages, once a day, no login, no tricks.
const ctx = $('Run context').first().json;
const clients = $('Get clients').all().map((i) => i.json).filter((c) => c.site_id && c.homepage_url);
// SIMULATION ADAPTER: the fictional sites are served by one n8n webhook, so the simulated day travels as a query parameter.
// In production this would simply be the client's homepage URL.
const pageUrl = (c) => c.homepage_url + '&file=page&day=' + ctx.day;
return clients.map((c) => ({ json: { ...ctx, site_id: c.site_id, client_name: c.client_name, homepage_url: c.homepage_url, url: pageUrl(c) } }));

// ---- shared parser: which scripts would actually run on this page? ----
// Only <script> tags count. Text, links, <code> blocks, HTML comments and data blocks
// such as <script type="application/ld+json"> are never executed, so they are never evidence.
const RUNNABLE_TYPES = ['', 'text/javascript', 'application/javascript', 'module', 'text/ecmascript', 'application/ecmascript'];
function parseScripts(html) {
  const clean = String(html || '').replace(/<!--[\s\S]*?-->/g, '');
  const out = [];
  const re = /<script\b([^>]*)>([\s\S]*?)<\/script\s*>/gi;
  let m;
  while ((m = re.exec(clean))) {
    const attrs = m[1] || '';
    const typeMatch = attrs.match(/\btype\s*=\s*["']?([^"'\s>]+)/i);
    const type = typeMatch ? typeMatch[1].toLowerCase() : '';
    if (!RUNNABLE_TYPES.includes(type)) continue;
    const srcMatch = attrs.match(/\bsrc\s*=\s*["']?([^"'\s>]+)/i);
    let src = srcMatch ? srcMatch[1] : '';
    if (src.startsWith('//')) src = 'https:' + src;
    out.push({ src, code: (m[2] || '').trim() });
  }
  return out;
}
const gtmIdsIn = (scripts) => [...new Set(scripts.flatMap((s) => (s.src + ' ' + s.code).match(/\bGTM-[A-Z0-9]{4,10}\b/g) || []))];
const swRegistered = (scripts) => [...new Set(scripts.flatMap((s) => [...s.code.matchAll(/serviceWorker\.register\(\s*["']([^"']+)["']/g)].map((x) => x[1])))];
// ---- end of shared parser ----

// For every page that loaded (HTTP 200): find GTM container IDs and service worker paths, and plan those fetches.
// Service worker paths = the standard paths from the signature table + any path the page itself registers.
const ctx = $('Run context').first().json;
const plans = $('Plan page requests').all().map((i) => i.json);
const sigs = $('Get signatures').all().map((i) => i.json).filter((s) => s.vendor);
const standardSwPaths = [...new Set(sigs.map((s) => s.sw_path).filter(Boolean))];
// SIMULATION ADAPTER: in production a service worker URL is new URL(path, homepage) and a container is
// https://www.googletagmanager.com/gtm.js?id=<GTM ID>. Here both come from the mock webhook.
const swUrl = (p, path) => p.homepage_url + '&file=sw&path=' + encodeURIComponent(path) + '&day=' + ctx.day;
const gtmUrl = (p, id) => p.homepage_url.split('?')[0] + '?file=gtm&id=' + encodeURIComponent(id) + '&day=' + ctx.day;
const bodyOf = (r) => (typeof r.data === 'string' ? r.data : typeof r.body === 'string' ? r.body : '');

const jobs = [];
$input.all().forEach((item, i) => {
  const p = plans[i];
  const r = item.json || {};
  if (Number(r.statusCode) !== 200) return; // blocked or broken: we do not try other files to get around it
  const scripts = parseScripts(bodyOf(r));
  swRegistered(scripts).concat(standardSwPaths).filter((v, k, a) => a.indexOf(v) === k)
    .forEach((path) => jobs.push({ json: { site_id: p.site_id, kind: 'sw', file: path, url: swUrl(p, path) } }));
  gtmIdsIn(scripts).forEach((id) => jobs.push({ json: { site_id: p.site_id, kind: 'gtm', file: id, url: gtmUrl(p, id) } }));
});
// Keeps the run going on a day when no page loaded (e.g. every site blocked): one empty job, no request is made.
if (!jobs.length) jobs.push({ json: { site_id: '', kind: 'none', file: '', url: '' } });
return jobs;

// ---- shared parser: which scripts would actually run on this page? ----
// Only <script> tags count. Text, links, <code> blocks, HTML comments and data blocks
// such as <script type="application/ld+json"> are never executed, so they are never evidence.
const RUNNABLE_TYPES = ['', 'text/javascript', 'application/javascript', 'module', 'text/ecmascript', 'application/ecmascript'];
function parseScripts(html) {
  const clean = String(html || '').replace(/<!--[\s\S]*?-->/g, '');
  const out = [];
  const re = /<script\b([^>]*)>([\s\S]*?)<\/script\s*>/gi;
  let m;
  while ((m = re.exec(clean))) {
    const attrs = m[1] || '';
    const typeMatch = attrs.match(/\btype\s*=\s*["']?([^"'\s>]+)/i);
    const type = typeMatch ? typeMatch[1].toLowerCase() : '';
    if (!RUNNABLE_TYPES.includes(type)) continue;
    const srcMatch = attrs.match(/\bsrc\s*=\s*["']?([^"'\s>]+)/i);
    let src = srcMatch ? srcMatch[1] : '';
    if (src.startsWith('//')) src = 'https:' + src;
    out.push({ src, code: (m[2] || '').trim() });
  }
  return out;
}
const gtmIdsIn = (scripts) => [...new Set(scripts.flatMap((s) => (s.src + ' ' + s.code).match(/\bGTM-[A-Z0-9]{4,10}\b/g) || []))];
const swRegistered = (scripts) => [...new Set(scripts.flatMap((s) => [...s.code.matchAll(/serviceWorker\.register\(\s*["']([^"']+)["']/g)].map((x) => x[1])))];
// ---- end of shared parser ----

// RULE-BASED DETECTION. No AI. A vendor counts as installed only when its loader is found in code that runs:
// a <script> on the page or a tag inside the page's GTM container. Service worker files are extra evidence.
const sigs = $('Get signatures').all().map((i) => i.json).filter((s) => s.vendor);
const plans = $('Plan page requests').all().map((i) => i.json);
const pages = $('Fetch homepage').all().map((i) => i.json);
const jobs = $('Plan file checks').all().map((i) => i.json);
const files = $input.all().map((i) => i.json);
const bodyOf = (r) => (typeof r.data === 'string' ? r.data : typeof r.body === 'string' ? r.body : '');
const pageSigs = sigs.filter((s) => String(s.where_to_look).includes('script') || String(s.where_to_look).includes('gtm'));
const swSigs = sigs.filter((s) => String(s.where_to_look).includes('sw'));
// GTM stores tag HTML as an escaped JavaScript string: < is <, \/ is /, \" is ".
const unescapeGtm = (t) => String(t).replace(/\\u003c/gi, '<').replace(/\\u003e/gi, '>').replace(/\\u0026/gi, '&').replace(/\\\//g, '/').replace(/\\"/g, '"');
const snippetAround = (text, needle) => {
  const at = text.toLowerCase().indexOf(needle.toLowerCase());
  if (at < 0) return '';
  return text.slice(Math.max(0, at - 40), at + needle.length + 40).replace(/\s+/g, ' ').trim();
};
// Checks one list of runnable scripts against the page signatures.
function matchScripts(scripts, whereLabel, fileLabel) {
  const found = [];
  scripts.forEach((s) => {
    const text = (s.src + '\n' + s.code);
    pageSigs.forEach((sig) => {
      if (text.toLowerCase().includes(String(sig.pattern).toLowerCase())) {
        found.push({ vendor: sig.vendor, is_ours: sig.is_ours === true, where: whereLabel, file: fileLabel,
          fragment: s.src && s.src.toLowerCase().includes(String(sig.pattern).toLowerCase()) ? '<script src="' + s.src + '">' : snippetAround(s.code, sig.pattern) });
      }
    });
  });
  return found;
}

return plans.map((p, i) => {
  const page = pages[i] || {};
  const status = Number(page.statusCode) || 0;
  const evidence = [];
  const swNotes = [];
  if (status === 200) {
    evidence.push(...matchScripts(parseScripts(bodyOf(page)), 'page script', 'homepage HTML'));
    jobs.forEach((job, k) => {
      if (job.site_id !== p.site_id) return;
      const r = files[k] || {};
      const ok = Number(r.statusCode) === 200;
      if (job.kind === 'gtm') {
        if (!ok) { swNotes.push('GTM container ' + job.file + ' not readable (HTTP ' + (r.statusCode || 'error') + ')'); return; }
        evidence.push(...matchScripts(parseScripts(unescapeGtm(bodyOf(r))), 'GTM container', 'gtm.js?id=' + job.file));
      }
      if (job.kind === 'sw' && ok) {
        const body = bodyOf(r);
        swSigs.forEach((sig) => {
          if (body.toLowerCase().includes(String(sig.pattern).toLowerCase())) {
            evidence.push({ vendor: sig.vendor, is_ours: sig.is_ours === true, where: 'service worker', file: job.file, fragment: snippetAround(body, sig.pattern) });
          }
        });
      }
    });
  }
  // One evidence line per vendor + place + file is enough.
  const seen = new Set();
  const uniq = evidence.filter((e) => { const k = e.vendor + e.where + e.file; if (seen.has(k)) return false; seen.add(k); return true; });
  const loaders = uniq.filter((e) => e.where !== 'service worker');
  const oursFound = loaders.some((e) => e.is_ours);
  const competitors = [...new Set(loaders.filter((e) => !e.is_ours).map((e) => e.vendor))].sort();
  const oursSwOnly = !oursFound && uniq.some((e) => e.is_ours && e.where === 'service worker');
  if (oursSwOnly) swNotes.push('our service worker file is still on the server, but no page loads our script');
  return { json: { run_id: p.run_id, scope: p.scope, day: p.day, site_id: p.site_id, client_name: p.client_name,
    http_status: status, ours_found: oursFound, competitors, evidence: uniq, notes: swNotes } };
});

// CHANGE RULE. A change only becomes an alert when two successful scans in a row show the same change.
// Levels: urgent = our script is gone; high = a competitor's script appeared; info = the site cannot be checked.
const RULES = { confirmScans: 2, blockedStatuses: [401, 403, 429] };
const obs = $('Detect integrations').all().map((i) => i.json);
const ctx = $('Run context').first().json;
const prevRows = $input.all().map((i) => i.json).filter((r) => r.site_id && r.scope === ctx.scope);
const prevBy = Object.fromEntries(prevRows.map((r) => [r.site_id, r]));
const list = (v) => String(v || '').split('|').map((x) => x.trim()).filter(Boolean);

return obs.map((o) => {
  const prev = prevBy[o.site_id];
  const st = prev ? { ours_confirmed: prev.ours_confirmed === true, competitors_confirmed: prev.competitors_confirmed || '',
    pending_signal: prev.pending_signal || '', pending_count: Number(prev.pending_count) || 0 }
    : null;
  let result, level = '', alert = false, signal = '', note = '';
  let next = st ? { ...st } : null;

  if (RULES.blockedStatuses.includes(o.http_status)) {
    result = 'cannot_check'; level = 'info';
    note = 'The site blocks automated requests (HTTP ' + o.http_status + '). Not retried and not worked around; check by hand or ask the client.';
  } else if (o.http_status !== 200) {
    result = 'error_skipped';
    note = 'HTTP ' + (o.http_status || 'no response') + ': day skipped, previous state and pending change kept.';
  } else if (!st) {
    result = 'baseline';
    next = { ours_confirmed: o.ours_found, competitors_confirmed: o.competitors.join('|'), pending_signal: '', pending_count: 0 };
    note = o.ours_found ? 'First scan: our script found.' : 'First scan: our script NOT found. Check the installation by hand.';
  } else {
    const parts = [];
    if (st.ours_confirmed && !o.ours_found) parts.push('ours_missing');
    o.competitors.filter((c) => !list(st.competitors_confirmed).includes(c)).forEach((c) => parts.push('competitor:' + c));
    signal = parts.sort().join('|');
    if (!signal) {
      // Good news (our script back, a competitor gone) is accepted at once: it cannot cause a false alarm.
      result = (o.ours_found !== st.ours_confirmed || o.competitors.join('|') !== st.competitors_confirmed) ? 'recovered' : 'no_change';
      next = { ours_confirmed: o.ours_found, competitors_confirmed: o.competitors.join('|'), pending_signal: '', pending_count: 0 };
    } else if (signal === st.pending_signal && st.pending_count + 1 >= RULES.confirmScans) {
      result = 'alert'; alert = true;
      level = signal.includes('ours_missing') ? 'urgent' : 'high';
      next = { ours_confirmed: o.ours_found, competitors_confirmed: o.competitors.join('|'), pending_signal: '', pending_count: 0 };
      note = 'Confirmed on ' + RULES.confirmScans + ' scans in a row.';
    } else {
      result = 'pending';
      next = { ...st, pending_signal: signal, pending_count: 1 };
      note = 'Change seen once. Waiting for the next scan to confirm.';
    }
  }
  if (o.notes.length) note = (note ? note + ' ' : '') + 'Notes: ' + o.notes.join('; ') + '.';
  const actual = alert ? level : result === 'cannot_check' ? 'cannot_check' : 'none';
  return { json: {
    run_id: o.run_id, scope: o.scope, day: o.day, site_id: o.site_id, client_name: o.client_name,
    http_status: o.http_status, result, level, alert, actual, ours_found: o.ours_found,
    competitors_found: o.competitors.join('|'), signal,
    evidence: JSON.stringify(o.evidence), note,
    keep_state: next === null ? false : true,
    state_ours_confirmed: next ? next.ours_confirmed : false,
    state_competitors_confirmed: next ? next.competitors_confirmed : '',
    state_pending_signal: next ? next.pending_signal : '',
    state_pending_count: next ? next.pending_count : 0,
  } };
});

// Last step of every run: one summary line. The test workflow waits for this before scanning the next day.
const rows = $('Compare with previous state').all().map((i) => i.json);
const count = (r) => rows.filter((x) => x.result === r).length;
return [{ json: { run_id: rows[0] && rows[0].run_id, scope: rows[0] && rows[0].scope, day: rows[0] && rows[0].day, sites: rows.length,
  alerts: rows.filter((x) => x.alert).map((x) => x.site_id + ' ' + x.level + ' ' + x.signal),
  pending: count('pending'), cannot_check: count('cannot_check'), errors_skipped: count('error_skipped') } }];
